import csv, collections, statistics

# Check VAV_F3_Z01 damper SP and any other F3_Z01-related points monthly
tsids = {
    'VAV_F3_Z01_damper_sp': 'de92aecc-fc37-5d28-a0b6-fb34b4c34747',
    'F3_Z01_temp': 'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
}
wanted = set(tsids.values())
inv = {v: k for k, v in tsids.items()}

by = {n: [] for n in tsids}
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        if row['timeseries_id'] in wanted:
            by[inv[row['timeseries_id']]].append((row['timestamp'], float(row['value'])))

for name in tsids:
    pts = sorted(by[name])
    by_m = collections.defaultdict(list)
    for ts, v in pts:
        by_m[ts[:7]].append(v)
    months = sorted(by_m)
    print(f"\n{name}")
    print("  ".join(f"{m[2:]}={statistics.mean(by_m[m]):.2f}" for m in months))
